steps.code:
album_library_ids = set()
page_index = 0
while True:
    res = apis.spotify.show_album_library(access_token=access_token, page_index=page_index, page_limit=20)
    if not res:
        break
    for album in res:
        album_library_ids.update(album.get('song_ids', []))
    page_index += 1
print(f"Album library songs: {len(album_library_ids)}")

all_playlist_ids = set()
page_index = 0
while True:
    res = apis.spotify.show_playlist_library(access_token=access_token, page_index=page_index, page_limit=20)
    if not res:
        break
    for pl in res:
        all_playlist_ids.add(pl['playlist_id'])
    page_index += 1
print(f"Total playlists: {len(all_playlist_ids)}")

