        break
    album_library.extend(page)
    page_index += 1

album_song_ids = set()
for album in album_library:
    for sid in album["song_ids"]:
        album_song_ids.add(sid)
print(f"Album library songs count: {len(album_song_ids)}")

playlist_library = []
page_index = 0
while True:
