        break
    playlist_library.extend(page)
    page_index += 1

playlist_song_ids = set()
for playlist in playlist_library:
    for sid in playlist["song_ids"]:
        playlist_song_ids.add(sid)
print(f"Playlist library songs count: {len(playlist_song_ids)}")

