steps.code:
album_song_ids = set()

page_index = 0
while True:
    page = apis.spotify.show_album_library(access_token=access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    for album in page:
        album_song_ids.update(album.get('song_ids', []))
    if len(page) < 20:
        break
    page_index += 1

print(f"Album library song IDs: {len(album_song_ids)}")

playlist_ids = []
page_index = 0
while True:
    page = apis.spotify.show_playlist_library(access_token=access_token, page_index=page_index, page_limit=20)
    if not page:
        break
    for playlist in page:
        playlist_ids.append(playlist['playlist_id'])
    if len(page) < 20:
        break
    page_index += 1

print(f"Total playlists: {len(playlist_ids)}")

