roommate_emails = ["an-harrison@gmail.com", "mel.bailey@gmail.com", "nicholas.weber@gmail.com"]
transactions_to_like = []
for email in roommate_emails:
    page_index = 0
    while True:
        txns = apis.venmo.show_transactions(access_token=access_token, user_email=email, min_created_at="2023-01-01", max_created_at="2023-12-31", page_index=page_index, page_limit=20)
        if not txns:
            break
        for t in txns:
            if not t.get("liked", False):
                transactions_to_like.append(t["transaction_id"])
        page_index += 1
print(len(transactions_to_like))

for tid in transactions_to_like:
    apis.venmo.like_transaction(access_token=access_token, transaction_id=tid)
print("Done liking transactions.")

