steps.code:
playlist_songs_map = {}
for pl in all_playlists:
    pl_id = pl['playlist_id']
    details = apis.spotify.show_playlist(playlist_id=pl_id, access_token=access_token)
    playlist_songs_map[pl_id] = details['songs']

all_song_ids = set()
for songs in playlist_songs_map.values():
    for s in songs:
        all_song_ids.add(s['id'])
print(f"Total unique songs across all playlists: {len(all_song_ids)}")

song_play_counts = {}
for sid in all_song_ids:
    song_info = apis.spotify.show_song(song_id=sid)
    song_play_counts[sid] = song_info['play_count']

print(f"Collected play counts for {len(song_play_counts)} songs")

most_played = {}
for pl_id, songs in playlist_songs_map.items():
    if not songs: continue
    best_song = max(songs, key=lambda s: song_play_counts.get(s['id'], 0))
    most_played[pl_id] = best_song['id']
print(most_played)

